import{c as t,Q as r,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"新領域研究報告 2026-07-03：主動推論（Active Inference） × 機器卸學習（Machine Unlearning）","description":"","frontmatter":{"date":"2026-07-03","archived_items":3,"dedup_verified":true,"domains":["active-inference","machine-unlearning"],"grounded_sources":[2604.15679,2606.15877,2605.01735,"https://activeinference.github.io/","https://arxiv.org/abs/2603.20927"],"source_routine":"routine-e","type":"new-domain-report"},"headers":[],"relativePath":"research/reports/2026-07-03-new-domain-active-inference-machine-unlearning.md","filePath":"research/reports/2026-07-03-new-domain-active-inference-machine-unlearning.md","lastUpdated":1785909234000}'),i={name:"research/reports/2026-07-03-new-domain-active-inference-machine-unlearning.md"};function o(c,e,d,s,h,l){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="新領域研究報告-2026-07-03-主動推論-active-inference-×-機器卸學習-machine-unlearning" tabindex="-1">新領域研究報告 2026-07-03：主動推論（Active Inference） × 機器卸學習（Machine Unlearning） <a class="header-anchor" href="#新領域研究報告-2026-07-03-主動推論-active-inference-×-機器卸學習-machine-unlearning" aria-label="Permalink to &quot;新領域研究報告 2026-07-03：主動推論（Active Inference） × 機器卸學習（Machine Unlearning）&quot;">​</a></h1><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>本次探勘發現兩個 workspace 完全未覆蓋的前沿：(1) <strong>Active Inference（主動推論）</strong>—— 源於神經科學自由能原理（Free Energy Principle）的替代智能範式，2026 年出現將其應用於 階層式規劃（successor representations）與重新詮釋 LLM chain-of-thought 失效模式的新論文； (2) <strong>Machine Unlearning（機器卸學習）</strong>——AI 治理/合規技術支柱，2026 年 5 月新論文提出 無需存取原始訓練語料即可選擇性抹除特定內容的幾何方法。兩者皆與 workspace 現有的 LLM/agent 中心版圖形成互補而非重疊。</p><h2 id="為何是「新」領域-反回音室證明" tabindex="-1">為何是「新」領域（反回音室證明） <a class="header-anchor" href="#為何是「新」領域-反回音室證明" aria-label="Permalink to &quot;為何是「新」領域（反回音室證明）&quot;">​</a></h2><p>去重驗證（可機械確認，執行 <code>grep -ic</code> 於 /tmp/covered_topics.txt + /tmp/covered_paper_terms.txt）：</p><table tabindex="0"><thead><tr><th>候選領域核心詞</th><th>covered_topics.txt 命中</th><th>covered_paper_terms.txt 命中</th><th>合計</th><th>判定</th></tr></thead><tbody><tr><td><code>active-inference</code> / <code>active inference</code></td><td>0</td><td>0</td><td><strong>0</strong></td><td>✅ 新邊疆</td></tr><tr><td><code>free-energy</code> / <code>free energy</code></td><td>0</td><td>0</td><td><strong>0</strong></td><td>✅ 新邊疆</td></tr><tr><td><code>unlearn</code></td><td>0</td><td>0</td><td><strong>0</strong></td><td>✅ 新邊疆</td></tr></tbody></table><p>對照：本次搜尋亦命中 <code>world-model</code>（0 命中，但屬前次 2026-06-28 探勘鄰近主題，未選為本次主題以避免鄰域重疊）、 <code>neuromorphic</code>（既有 INDEX 命中 1，回音室內排除）、<code>formal-verification</code>（既有 INDEX 命中 1，回音室內排除）。 Workspace 451 篇論文高度集中於 LLM/agent/RAG/harness，兩個新領域皆未曾觸及。</p><h3 id="候選領域比較-本次搜尋共產出-6-個候選-取-top-2" tabindex="-1">候選領域比較（本次搜尋共產出 6 個候選，取 Top 2） <a class="header-anchor" href="#候選領域比較-本次搜尋共產出-6-個候選-取-top-2" aria-label="Permalink to &quot;候選領域比較（本次搜尋共產出 6 個候選，取 Top 2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>候選領域</th><th>升溫信號(1-5)</th><th>去重結果</th><th>取捨理由</th></tr></thead><tbody><tr><td>active-inference</td><td>4</td><td>0 命中 ✅</td><td>選中：理論範式完全新穎 + 直接對應 workspace 關注的 CoT/reasoning 議題</td></tr><tr><td>machine-unlearning</td><td>4</td><td>0 命中 ✅</td><td>選中：AI 治理/合規技術，與既有 security-hygiene 規則互補</td></tr><tr><td>privacy-preserving 3D segmentation</td><td>2</td><td>0 命中，但過於窄眾</td><td>排除：屬電腦視覺子問題，非獨立研究領域，槓桿有限</td></tr><tr><td>structure-from-motion</td><td>1</td><td>0 命中，但非「新」</td><td>排除：電腦視覺經典問題，非前沿升溫信號</td></tr><tr><td>world-model</td><td>3</td><td>0 命中，但鄰近前次探勘</td><td>排除：與 2026-06-28 神經形態/機器人領域高度鄰接，選入恐落入「準回音室」</td></tr><tr><td>neuromorphic / formal-verification-robotics</td><td>—</td><td>既有 INDEX 命中 1</td><td>排除：回音室內（前次已探勘）</td></tr></tbody></table><h2 id="領域一-active-inference-主動推論-自由能原理" tabindex="-1">領域一：Active Inference（主動推論 / 自由能原理） <a class="header-anchor" href="#領域一-active-inference-主動推論-自由能原理" aria-label="Permalink to &quot;領域一：Active Inference（主動推論 / 自由能原理）&quot;">​</a></h2><h3 id="核心問題-範式" tabindex="-1">核心問題 / 範式 <a class="header-anchor" href="#核心問題-範式" aria-label="Permalink to &quot;核心問題 / 範式&quot;">​</a></h3><p>Active inference 是 Karl Friston 提出的自由能原理（FEP）在行動與規劃上的延伸： agent 透過最小化「預期自由能」（expected free energy）統一感知推論與行動選擇， 而非主流強化學習 / LLM-agent 範式的獎勵最大化。這代表一套與 Transformer-centric 深度學習完全不同的智能理論基礎，源自計算神經科學而非工程優化。</p><h3 id="關鍵玩家-代表工作" tabindex="-1">關鍵玩家 / 代表工作 <a class="header-anchor" href="#關鍵玩家-代表工作" aria-label="Permalink to &quot;關鍵玩家 / 代表工作&quot;">​</a></h3><ul><li><strong>Prashant Rangarajan, Rajesh P. N. Rao</strong>（華盛頓大學）— <a href="https://arxiv.org/abs/2604.15679" target="_blank" rel="noreferrer">Hierarchical Active Inference using Successor Representations</a> （2026-04-17）：首次將學習型階層狀態/動作抽象應用於 FEP-based active inference， 在 four-rooms、PointMaze、Mountain Car 等 benchmark 驗證規劃效率提升。</li><li><strong>Alex Bogdan</strong> — <a href="https://arxiv.org/abs/2606.15877" target="_blank" rel="noreferrer">Free Energy Heuristics</a>（2026-06-14）： 用 active inference 框架解釋 LLM chain-of-thought 為何在高 meta-uncertainty 任務上 隨推理鏈變長而準確率下降（FEH-79 benchmark，7 模型 × 7,875 回應，高不確定性情境下降 17.3pp）。</li><li><strong>Bert de Vries</strong> — <a href="https://arxiv.org/abs/2603.20927" target="_blank" rel="noreferrer">Active Inference for Physical AI Agents</a> （2026-03-21）：工程視角，主張 FEP 為具身 AI 提供比純 RL 更具原則性的基礎。</li><li>社群節點：<a href="https://activeinference.github.io/" target="_blank" rel="noreferrer">Active Inference Institute</a> 持續產出跨學科整合研究。</li></ul><h3 id="當前進展與開放問題" tabindex="-1">當前進展與開放問題 <a class="header-anchor" href="#當前進展與開放問題" aria-label="Permalink to &quot;當前進展與開放問題&quot;">​</a></h3><p>進展：已從純理論延伸至階層式規劃（2604.15679）與 LLM 推理失效解釋（2606.15877）兩個實務落地方向， 顯示該範式正從神經科學圈向主流 ML/LLM 研究滲透。 開放問題：缺乏大規模、與 Transformer 架構相容的 active inference 實作； 計算複雜度（變分推論）在高維狀態空間的可擴展性仍待驗證。</p><h2 id="領域二-machine-unlearning-機器卸學習" tabindex="-1">領域二：Machine Unlearning（機器卸學習） <a class="header-anchor" href="#領域二-machine-unlearning-機器卸學習" aria-label="Permalink to &quot;領域二：Machine Unlearning（機器卸學習）&quot;">​</a></h2><h3 id="核心問題-範式-1" tabindex="-1">核心問題 / 範式 <a class="header-anchor" href="#核心問題-範式-1" aria-label="Permalink to &quot;核心問題 / 範式&quot;">​</a></h3><p>如何在不重新訓練整個模型的前提下，讓已訓練模型「遺忘」特定資料點的影響—— 對應 GDPR 被遺忘權、版權移除、有害記憶抹除等法規與安全需求。 核心張力：完全重訓成本過高，但不當的近似卸學習可能殘留可被攻擊者復原的痕跡。</p><h3 id="關鍵玩家-代表工作-1" tabindex="-1">關鍵玩家 / 代表工作 <a class="header-anchor" href="#關鍵玩家-代表工作-1" aria-label="Permalink to &quot;關鍵玩家 / 代表工作&quot;">​</a></h3><ul><li><strong>Chenchen Tan et al.</strong>（Monash University 等）— <a href="https://arxiv.org/abs/2605.01735" target="_blank" rel="noreferrer">Geometric Unlearning for LLMs with Minimal Data Disclosure</a> （2026-05-28）：直接操作 prompt-conditioned 隱藏狀態、不需存取原始訓練語料， 從少量安全參考 prompt 蒸餾低秩 safe-behavior 子空間，ToFU/UnlearnPII benchmark 驗證。</li><li>延伸方向（未歸檔，供後續追蹤）：Model State Arithmetic（<a href="https://arxiv.org/abs/2506.20941" target="_blank" rel="noreferrer">2506.20941</a>， 利用歷史 checkpoint 估計並抵銷資料影響，ICLR 2026 接受）、 DurableUn（量化引發的卸學習復原攻擊，2026-05）。</li></ul><h3 id="當前進展與開放問題-1" tabindex="-1">當前進展與開放問題 <a class="header-anchor" href="#當前進展與開放問題-1" aria-label="Permalink to &quot;當前進展與開放問題&quot;">​</a></h3><p>進展：2026 年方法逐漸從「需存取原始語料的近似再訓練」轉向「僅需少量參考資料的隱藏狀態層級操作」， 大幅降低隱私與運算成本。開放問題：卸學習後的殘留可復原性（如量化引發的復原攻擊）仍是活躍研究方向， 缺乏統一的卸學習完整性驗證標準。</p><h2 id="對本-workspace-的潛在槓桿-誠實標「待驗證」" tabindex="-1">對本 workspace 的潛在槓桿（誠實標「待驗證」） <a class="header-anchor" href="#對本-workspace-的潛在槓桿-誠實標「待驗證」" aria-label="Permalink to &quot;對本 workspace 的潛在槓桿（誠實標「待驗證」）&quot;">​</a></h2><ul><li><strong>待驗證</strong>：Active inference 的「預期自由能最小化」框架，若能對照 workspace <code>self-escalate</code> 收斂判斷機制，或可提供替代的不確定性量化視角（非 LLM 自評的收斂訊號）。</li><li><strong>待驗證</strong>：Machine unlearning 技術若成熟，對 <code>.claude/rules/security-hygiene.md</code> 的憑證/敏感資料處理紀律可能有互補價值（模型層級 vs 檔案層級的資料清除）。</li><li>兩者短期內對現有 harness 規則無直接修改需求，僅供後續追蹤觀察。</li><li><strong>兩領域交叉點（推測性，未驗證）</strong>：Active inference 的「預期自由能」與 machine unlearning 的「選擇性資訊移除」皆涉及「模型應保留/捨棄哪些資訊」的決策，理論上可能存在共通的 資訊理論視角（如何量化「保留有用資訊 vs 移除目標資訊」的權衡），但目前兩個研究社群 尚無交叉引用，此連結純屬本報告觀察，未經文獻驗證，僅供未來探索方向參考。</li></ul><h2 id="收錄來源" tabindex="-1">收錄來源 <a class="header-anchor" href="#收錄來源" aria-label="Permalink to &quot;收錄來源&quot;">​</a></h2><ul><li><code>research/papers/2026-04-17-hierarchical-active-inference-successor-representations-2604-15679.md</code></li><li><code>research/papers/2026-06-14-free-energy-heuristics-active-inference-2606-15877.md</code></li><li><code>research/papers/2026-05-28-geometric-unlearning-llms-2605-01735.md</code></li></ul><h2 id="後續追蹤建議" tabindex="-1">後續追蹤建議 <a class="header-anchor" href="#後續追蹤建議" aria-label="Permalink to &quot;後續追蹤建議&quot;">​</a></h2><p>若 active inference 在 LLM reasoning 失效解釋上持續產出（如 2606.15877 後續引用）， 建議納入 WEEKLY-FOCUS 觀察名單；machine unlearning 若出現與 workspace 資安紀律直接相關的 應用（如 credential/PII 卸學習方法），建議下次 Routine E 或 Routine D 深化。</p>',29)])])}const f=t(i,[["render",o]]);export{p as __pageData,f as default};
